<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { Archive, FolderOpen, Plus, Search } from 'lucide-vue-next'
import Modal from '../components/Modal.vue'
import Pager from '../components/Pager.vue'
import { api, loadProjects, messageOf, notify, pickFields, projectStatuses, query } from '../api'
import type { Page, Project } from '../types'
const props=defineProps<{revision:number}>();const emit=defineEmits<{changed:[];tasks:[id:string]}>()
const projects=ref<Project[]>([]),total=ref(0),offset=ref(0),filter=ref(''),search=ref(''),error=ref(''),loading=ref(false),open=ref(false),saving=ref(false),formError=ref(''),editing=ref<Project>();const limit=30
const blank=()=>({code:'',name:'',customer:'',phase:'',manager:'',start_date:'',end_date:'',status:'active',description:''});const form=reactive(blank())
async function load(){loading.value=true;error.value='';try{const page=await api<Page<Project>>(`/api/projects?${query({status:filter.value,q:search.value,limit,offset:offset.value})}`);projects.value=page.items;total.value=page.total}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
onMounted(load);watch(()=>props.revision,load);watch(filter,()=>{offset.value=0;void load()})
function edit(project?:Project){editing.value=project;Object.assign(form,project?pickFields(project,blank()):blank());formError.value='';open.value=true}
async function save(){if(saving.value)return;saving.value=true;formError.value='';try{await api(editing.value?`/api/projects/${editing.value.id}`:'/api/projects',{method:editing.value?'PATCH':'POST',body:JSON.stringify({...pickFields(form,blank()),...(editing.value?{version:editing.value.version}:{})})});open.value=false;notify(editing.value?'项目信息已保存':'项目已创建');await loadProjects();emit('changed');await load()}catch(e){formError.value=messageOf(e)}finally{saving.value=false}}
async function archive(project:Project){if(!window.confirm(`归档「${project.name}」后，项目及其任务、记录、日志和问题将只读。确定归档？`))return;try{await api(`/api/projects/${project.id}`,{method:'PATCH',body:JSON.stringify({status:'archived',version:project.version})});notify('项目已归档');await loadProjects();emit('changed');await load()}catch(e){notify(messageOf(e),true)}}
function page(next:number){offset.value=next;void load()}
</script>
<template><div class="page-heading"><div><h1>项目</h1><p class="page-description">每个项目的目标、进展和现场资料，放在一起。</p></div><button class="button primary" @click="edit()"><Plus :size="18"/>新建项目</button></div><form class="filter-bar" @submit.prevent="offset=0;load()"><div class="input-with-icon"><Search :size="16"/><input v-model="search" placeholder="搜索项目名称或编号" aria-label="搜索项目"/></div><select v-model="filter" aria-label="项目状态"><option value="">全部状态</option><option v-for="(name,key) in projectStatuses" :key="key" :value="key">{{name}}</option></select><button class="button subtle" type="submit">查询</button><span class="filter-total">{{total}} 个项目</span></form><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><div class="surface"><div v-if="loading" class="loading-message">正在读取项目…</div><div v-else-if="!projects.length" class="empty-state"><FolderOpen :size="38"/><h2>{{search||filter?'没有符合条件的项目':'建立你的第一个项目'}}</h2><p>{{search||filter?'试试调整关键词或状态筛选。':'填入名称即可开始，其他信息可以随时补充。'}}</p><button v-if="!search&&!filter" class="button primary" @click="edit()">新建项目</button></div><div v-else class="table-scroll"><table><thead><tr><th>项目</th><th>客户 / 阶段</th><th>负责人</th><th>计划周期</th><th>状态</th><th class="right">操作</th></tr></thead><tbody><tr v-for="p in projects" :key="p.id"><td><button class="table-title" @click="emit('tasks',p.id)">{{p.name}}</button><small>{{p.code||'未设编号'}}</small></td><td>{{p.customer||'—'}}<small>{{p.phase||'未设阶段'}}</small></td><td>{{p.manager||'—'}}</td><td class="date-cell">{{p.start_date||'未设置'}}<small>至 {{p.end_date||'未设置'}}</small></td><td><span class="badge" :class="p.status">{{projectStatuses[p.status]}}</span></td><td class="right"><div class="row-actions"><button class="text-button" @click="edit(p)">{{p.status==='archived'?'查看':'编辑'}}</button><button v-if="p.status!=='archived'" class="icon-button" title="归档项目" :aria-label="`归档项目 ${p.name}`" @click="archive(p)"><Archive :size="16"/></button></div></td></tr></tbody></table></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></div><Modal :open="open" :title="editing?.status==='archived'?'项目详情':editing?'编辑项目':'新建项目'" wide @close="!saving&&(open=false)"><form class="modal-body" @submit.prevent="save"><fieldset :disabled="editing?.status==='archived'||saving"><label>项目名称 <span class="required">*</span><input v-model="form.name" required maxlength="200" autofocus placeholder="例如：厂区设备改造"/></label><div class="form-row"><label>项目编号<input v-model="form.code" maxlength="80" placeholder="留空时由系统生成"/></label><label>客户<input v-model="form.customer" maxlength="200"/></label></div><div class="form-row"><label>当前阶段<input v-model="form.phase" maxlength="100" placeholder="例如：实施交付"/></label><label>项目负责人<input v-model="form.manager" maxlength="100"/></label></div><div class="form-row"><label>计划开始<input v-model="form.start_date" type="date"/></label><label>计划结束<input v-model="form.end_date" type="date" :min="form.start_date||undefined"/></label></div><label>项目状态<select v-model="form.status"><option v-for="(name,key) in projectStatuses" :key="key" :value="key" :disabled="key==='archived'">{{name}}</option></select></label><label>项目说明<textarea v-model="form.description" rows="3" placeholder="项目目标、范围或需要说明的事项"/></label></fieldset><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><span v-if="editing?.status==='archived'" class="muted">已归档，项目与关联内容只读</span><button v-else type="submit" class="button primary" :disabled="saving">{{saving?'正在保存…':'保存项目'}}</button></div></form></Modal></template>
